class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> wordSet(wordList.begin(), wordList.end());
        if (!wordSet.count(endWord)) return 0;
        unordered_set<string> beginSet{beginWord}, endSet{endWord};
        int length = 1;
        while (!beginSet.empty() && !endSet.empty()) {
            if (beginSet.size() > endSet.size()) swap(beginSet, endSet);
            unordered_set<string> nextSet;
            for (string word : beginSet) {
                for (int i = 0; i < (int)word.size(); ++i) {
                    char original = word[i];
                    for (char c = 'a'; c <= 'z'; ++c) {
                        word[i] = c;
                        if (endSet.count(word)) return length + 1;
                        if (wordSet.count(word)) {
                            nextSet.insert(word);
                            wordSet.erase(word);
                        }
                    }
                    word[i] = original;
                }
            }
            beginSet = move(nextSet);
            ++length;
        }
        return 0;
    }
};

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return 0;
        Set<String> beginSet = new HashSet<>();
        Set<String> endSet = new HashSet<>();
        beginSet.add(beginWord);
        endSet.add(endWord);
        int length = 1;
        while (!beginSet.isEmpty() && !endSet.isEmpty()) {
            if (beginSet.size() > endSet.size()) {
                Set<String> tmp = beginSet;
                beginSet = endSet;
                endSet = tmp;
            }
            Set<String> nextSet = new HashSet<>();
            for (String word : beginSet) {
                char[] chs = word.toCharArray();
                for (int i = 0; i < chs.length; i++) {
                    char orig = chs[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        chs[i] = c;
                        String nextWord = new String(chs);
                        if (endSet.contains(nextWord)) return length + 1;
                        if (wordSet.contains(nextWord)) {
                            nextSet.add(nextWord);
                            wordSet.remove(nextWord);
                        }
                    }
                    chs[i] = orig;
                }
            }
            beginSet = nextSet;
            length++;
        }
        return 0;
    }
}

var ladderLength = function(beginWord, endWord, wordList) {
    const wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return 0;
    let beginSet = new Set([beginWord]);
    let endSet = new Set([endWord]);
    let length = 1;
    while (beginSet.size > 0 && endSet.size > 0) {
        if (beginSet.size > endSet.size) {
            const tmp = beginSet;
            beginSet = endSet;
            endSet = tmp;
        }
        const nextSet = new Set();
        for (const word of beginSet) {
            for (let i = 0; i < word.length; i++) {
                for (let code = 97; code <= 122; code++) {
                    const c = String.fromCharCode(code);
                    const nextWord = word.slice(0, i) + c + word.slice(i + 1);
                    if (endSet.has(nextWord)) return length + 1;
                    if (wordSet.has(nextWord)) {
                        nextSet.add(nextWord);
                        wordSet.delete(nextWord);
                    }
                }
            }
        }
        beginSet = nextSet;
        length++;
    }
    return 0;
};
